import numpy as np
from scipy.optimize import curve_fit
d=np.array([[float(x.replace(',','.')) for x in l.split('\t')] for l in open('graphene.dat') if l.strip()])
x,y=d[:,0],d[:,1]
o=np.argsort(x); x=x[o]; y=y[o]

def lor(x,x0,g,A,off,sl=0): return off+sl*(x-x0)+A*g*g/((x-x0)**2+g*g)
def gau(x,x0,g,A,off,sl=0): return off+sl*(x-x0)+A*np.exp(-0.5*((x-x0)/g)**2)
def pv(x,x0,g,A,off,sl=0,eta=0.5):
    L=g*g/((x-x0)**2+g*g); G=np.exp(-0.5*((x-x0)/g)**2)
    return off+sl*(x-x0)+A*(eta*L+(1-eta)*G)

for name,lo,hi,x0,g,A,off in [('G',3600,4000,3745,20,11000,1900),('2D',6100,6600,6325,45,7500,6200)]:
    m=(x>=lo)&(x<=hi); xx,yy=x[m],y[m]
    print('\n=====',name,lo,hi,len(xx))
    for model,fn,p0 in [('lor',lor,[x0,g,A,off,0]),('gau',gau,[x0,g,A,off,0]),('pv',pv,[x0,g,A,off,0,0.5]),('lor0',lambda x,x0,g,A,off: lor(x,x0,g,A,off,0),[x0,g,A,off]),('gau0',lambda x,x0,g,A,off: gau(x,x0,g,A,off,0),[x0,g,A,off])]:
        try:
            popt,pcov=curve_fit(fn,xx,yy,p0=p0,maxfev=100000)
            r=yy-fn(xx,*popt)
            print(f"{model:5s} x0={popt[0]:9.3f} g={popt[1]:8.3f} A={popt[2]:9.2f} off={popt[3]:9.2f} sl={popt[4] if len(popt)>4 else 0:8.3f} rms={np.sqrt(np.mean(r*r)):8.2f} {'eta='+str(round(popt[5],3)) if len(popt)>5 else ''}")
        except Exception as e: print(model,'fail',e)
