import numpy as np
from scipy.optimize import curve_fit
d=np.array([[float(x.replace(',','.')) for x in l.split('\t')] for l in open('graphene.dat') if l.strip()])
x,y=d[:,0],d[:,1]
o=np.argsort(x); x=x[o]; y=y[o]
def lor(x,x0,g,A,off): return off+A*g*g/((x-x0)**2+g*g)
def gau(x,x0,g,A,off): return off+A*np.exp(-0.5*((x-x0)/g)**2)
for name,pk in [('G',3745),('2D',6327)]:
    print(name)
    for w in [50,75,100,125,150,200,250,300,400,500]:
        lo,hi=pk-w,pk+w; m=(x>=lo)&(x<=hi); xx,yy=x[m],y[m]
        try:
            pl,_=curve_fit(lor,xx,yy,p0=[pk,25 if name=='G' else 35,12000 if name=='G' else 8000,1500 if name=='G' else 5800],maxfev=200000)
            pg,_=curve_fit(gau,xx,yy,p0=[pk,20 if name=='G' else 30,12000 if name=='G' else 8000,1700 if name=='G' else 6000],maxfev=200000)
            rl=np.sqrt(np.mean((yy-lor(xx,*pl))**2)); rg=np.sqrt(np.mean((yy-gau(xx,*pg))**2))
            print(f"  w={w:3d} n={len(xx):3d} LOR x0={pl[0]:8.3f} g={pl[1]:7.2f} A={pl[2]:8.1f} off={pl[3]:8.1f} rms={rl:6.1f} | GAU x0={pg[0]:8.3f} g={pg[1]:7.2f} A={pg[2]:8.1f} off={pg[3]:8.1f} rms={rg:6.1f}")
        except Exception as e: print(w,'fail',e)
